try {
  const inputData = JSON.parse(query);
  let dataFetched;
  const listOfExercises = inputData.exercises.map(async (exercise) => {
    try {
      const options = {
        method: 'GET',
        url: `https://musclewiki-api.p.rapidapi.com/exercises/${exercise.id}`,
        params: {
          details: true,
          gender: 'male'
        },
        headers: {
          'x-rapidapi-host': 'musclewiki-api.p.rapidapi.com',
          'x-rapidapi-key': '299922e148msh9a1fbac3c90fe8cp11dcc5jsn34451e952600',
        },
      };

      const response = await this.helpers.request(options);
      const data = response;
      dataFetched = data

      return {
        name: data.name,
        difficulty: data.difficulty,
        steps: data.steps,
        videos: data.videos,
        // image: data.videos[0]?.og_image,
      };
    } catch (err) {
      return {
        queryData: 'query',
        message: 'Error while fetching exercise details',
        error: err.message,
        data: dataFetched,
      };
    }
  });

  const exercisesDetails = await Promise.all(listOfExercises);
  return JSON.stringify(exercisesDetails);
} catch (err) {
  return JSON.stringify({
    queryData: query,
    message: 'Error while parsing input data',
    error: err.message,
    data: null,
  });
}
